slugs={'Xi’an':'xian','Hong Kong':'hong-kong','Macao':'macao'}
intros={
'Beijing':'The scale is imperial, but the memorable moments are often small: breakfast at a neighbourhood stall, a turn into a quiet hutong, the first glimpse of a courtyard roof. Give Beijing enough days to move between its monumental history and everyday life without rushing.',
'Shanghai':'Shanghai rewards walking. Start with the grand riverfront, then turn towards leafy residential streets, small cafés and the everyday rhythms of the old lanes. Its pleasure lies in the contrast between a constantly changing skyline and details you only notice at street level.',
'Guilin':'The landscape is the reason to come, but slowing down is what makes it memorable. Limestone peaks rise above rivers, villages and fields. Spend part of the journey around Yangshuo, with enough time to enjoy rural paths between the famous viewpoints.',
'Chengdu':'This is a city that makes room for a long lunch and an even longer cup of tea. Pandas may bring you here, but parks, neighbourhood cooking and the rhythm of daily life are reasons to stay. A flexible afternoon can be as rewarding as a booked attraction.'}
cities=[]
for line in raw.splitlines():
 n,cn,r,p,d,s,ll,w,t,spots,food,tip=line.split('|');slug=slugs.get(n,n.lower().replace(' ','-'));lat,lng=map(float,ll.split(','))
 highlights=[{'name':x.split(':',1)[0],'description':x.split(':',1)[1]} for x in re.split(r';(?=[^;:]+:)',spots)]
 cities.append(dict(slug=slug,name=n,chinese=cn,region=r,province=p,days=d,season=s,lat=lat,lng=lng,wiki=w,tagline=t,description=intros.get(n,f'{t} Build your stay around {highlights[0]["name"]}, then make space for {highlights[1]["name"]} and the neighbourhoods in between. {tip}'),highlights=highlights,food=food,tip=tip,image=f'/travel/{slug}.jpg',source='https://en.wikipedia.org/wiki/'+w.replace(' ','_'),interests=['Culture','Food'] if r in ['East','Central','North'] else ['Nature','Culture']))
Path('src/lib/travel/cities.json').write_text(json.dumps(cities,ensure_ascii=False,indent=2)+'\n')
print('Created',len(cities),'destination records')
